item.command:
/bin/bash -lc "cat > index.html <<'EOF'
<"'!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<meta name="theme-color" content="#234c3e">
<title>Folio — Invoice overview</title>
<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='"'http://www.w3.org/2000/svg' viewBox='0 0 40 40'%3E%3Crect width='40' height='40' rx='10' fill='%23234c3e'/%3E%3Cpath d='M12 29V11h17v5H17v4h10v5H17v4z' fill='%23d8e6bd'/%3E%3C/svg%3E\">
<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">
<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>
<link href=\"https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;450;500;550;600;650;700&display=swap\" rel=\"stylesheet\">
<style>
:root {
  --canvas: #fafbf9; --surface: #ffffff; --sidebar: #f2f3ee; --ink: #222b26;
  --muted: #72776f; --subtle: #5f685f; --line: #e7e9e2; --control: #92998f;
  --green: #234c3e; --green-hover: #173b2e; --green-tint: #e4eade; --lime: #d9e6bb;
  --orange: #a44b30; --orange-tint: #fbede5; --paid: #3d6c4c; --paid-tint: #edf4ea;
  --pending: #8b6828; --pending-tint: #f9f2de; --draft: #646973; --draft-tint: #eff0f3;
  --radius: 10px; --radius-sm: 6px; --font: 'DM Sans', sans-serif;
  --shadow: 0 16px 64px #182b2226; --speed: 160ms;
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--canvas); color: var(--ink); font-family: var(--font); font-size: 14px; line-height: 1.5; -webkit-font-smoothing: antialiased; }
button, input, select { font: inherit; }
button, a, input, select { -webkit-tap-highlight-color: transparent; }
button { cursor: pointer; color: inherit; }
button { border: 0; }
a { color: inherit; }
button, input, select { transition: background var(--speed), border-color var(--speed), color var(--speed); }
button:focus-visible, a:focus-visible, input:focus-visible, select:focus-visible { outline: 2px solid var(--green); outline-offset: 3px; }
button:disabled { opacity: .35; cursor: default; }
svg.icon { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.65; stroke-linecap: round; stroke-linejoin: round; flex-shrink: 0; vertical-align: middle; }
.icon-sprite { position: absolute; width: 0; height: 0; overflow: hidden; }
.skip { position: fixed; left: 16px; top: -80px; z-index: 10; background: var(--green); color: white; padding: 12px 16px; border-radius: var(--radius-sm); }
.skip:focus { top: 16px; }
.sidebar { width: 224px; position: fixed; inset: 0 auto 0 0; padding: 36px 20px 20px; background: var(--sidebar); border-right: 1px solid var(--line); display: flex; flex-direction: column; z-index: 5; }
.brand { display: flex; align-items: center; gap: 10px; margin: 0 12px 44px; text-decoration: none; width: fit-content; }
.brand-mark { color: var(--green); width: 30px; height: 34px; }
.brand-name { font-size: 32px; line-height: 1; font-weight: 650; letter-spacing: -1.5px; }
.workspace { display: flex; gap: 10px; align-items: center; margin: 0 12px 32px; }
.workspace-icon { display: grid; place-items: center; width: 34px; height: 34px; border: 1px solid #d8dcd2; border-radius: 7px; background: #f9faf6; color: var(--green); }
.workspace-title { display: block; font-size: 13px; font-weight: 600; }
.workspace-sub { display: block; font-size: 11px; color: var(--subtle); }
.nav-label { font-size: 10px; color: var(--subtle); font-weight: 600; letter-spacing: 1.3px; margin: 0 12px 12px; text-transform: uppercase; }
.nav { display: flex; flex-direction: column; gap: 4px; }
.nav button { padding: 12px; min-height: 44px; display: flex; align-items: center; gap: 12px; text-align: left; background: transparent; border-radius: var(--radius-sm); color: var(--subtle); font-size: 13px; font-weight: 500; }
.nav button:hover { background: #e9ece3; color: var(--ink); }
.nav button.active { background: var(--green-tint); color: var(--green); font-weight: 650; }
.nav button .icon { width: 18px; height: 18px; }
.nav-count { margin-left: auto; font-size: 11px; min-width: 20px; text-align: center; color: var(--orange); background: #f2e2d5; border-radius: 4px; }
.nav-divider { height: 1px; background: #dfe3d8; margin: 24px 12px; }
.sidebar-bottom { margin-top: auto; padding-top: 48px; }
.local-note { display: flex; align-items: center; gap: 8px; color: var(--subtle); font-size: 11px; padding: 0 12px 24px; }
.local-note .icon { width: 15px; height: 15px; }
.profile { display: flex; align-items: center; gap: 12px; border-top: 1px solid #dfe3d8; padding: 20px 8px 0; }
.avatar { width: 36px; height: 36px; flex-shrink: 0; display: grid; place-items: center; border-radius: 50%; background: #e2d9c8; color: #5d5547; font-size: 11px; font-weight: 600; }
.profile strong { display: block; font-size: 12px; font-weight: 600; }
.profile span { font-size: 11px; color: var(--subtle); }
.main { margin-left: 224px; min-height: 100vh; }
.topbar { height: 76px; padding: 0 40px; display: flex; align-items: center; justify-content: space-between; gap: 16px; border-bottom: 1px solid var(--line); background: var(--surface); }
.breadcrumb { display: flex; gap: 12px; align-items: center; font-size: 12px; color: var(--muted); }
.breadcrumb .slash { color: #b4b9ad; }
.breadcrumb strong { color: var(--ink); font-weight: 500; }
.topbar-right { display: flex; align-items: center; gap: 16px; }
.sample { font-size: 10px; color: var(--subtle); padding: 4px 8px; border: 1px solid var(--line); border-radius: 4px; }
.date { display: flex; align-items: center; gap: 8px; color: var(--subtle); font-size: 12px; }
.date .icon { width: 15px; height: 15px; }
.menu-toggle { display: none "'!important; }
.content { max-width: 1456px; margin: 0 auto; padding: 36px 40px 32px; }
.page-heading { display: flex; justify-content: space-between; align-items: center; gap: 16px; margin-bottom: 28px; }
h1 { font-size: 30px; font-weight: 550; letter-spacing: -1px; line-height: 1.2; margin: 0 0 8px; }
.page-description { color: var(--muted); font-size: 13px; margin: 0; }
.btn { min-height: 44px; padding: 10px 16px; display: inline-flex; justify-content: center; align-items: center; gap: 8px; border-radius: var(--radius-sm); font-size: 12px; font-weight: 550; white-space: nowrap; }
.btn-primary { background: var(--green); color: white; }
.btn-primary:hover { background: var(--green-hover); }
.btn-primary:active { background: #102e23; }
.btn .icon { width: 17px; height: 17px; }
.btn-secondary { background: var(--surface); border: 1px solid var(--control); }
.btn-secondary:hover { background: var(--sidebar); }
.icon-btn { width: 44px; height: 44px; display: inline-flex; align-items: center; justify-content: center; background: transparent; border-radius: var(--radius-sm); color: var(--subtle); }
.icon-btn:hover { background: var(--sidebar); color: var(--green); }
.stats { display: grid; grid-template-columns: 1.12fr 1fr 1fr; gap: 20px; margin-bottom: 36px; }
.stat { min-width: 0; background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 20px 24px; position: relative; }
.stat-primary { background: var(--green); border-color: var(--green); color: #fff; }
.stat-top { display: flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 500; color: var(--subtle); margin-bottom: 12px; }
.stat-top .icon { width: 16px; height: 16px; }
.stat-primary .stat-top { color: #dce6d8; }
.stat-link { display: flex; align-items: center; justify-content: center; margin-left: auto; height: 24px; width: 24px; border-radius: 4px; background: transparent; color: inherit; }
.stat-link::after { content: '"''; position: absolute; width: 44px; height: 44px; }
.stat-link:hover { background: #e9ece3; color: var(--green); }
.stat-primary .stat-link:hover { background: #3a6050; color: white; }
.stat-value { font-size: clamp(28px, 2.7vw, 40px); line-height: 1.1; letter-spacing: -1.4px; font-weight: 500; font-variant-numeric: tabular-nums; white-space: nowrap; }
.stat-value .cents { font-size: .62em; letter-spacing: -.5px; opacity: .65; }
.stat-bottom { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-top: 16px; font-size: 11px; color: var(--muted); }
.stat-primary .stat-bottom { color: #c4d4c7; }
.microbars { display: flex; align-items: center; gap: 3px; width: 68px; height: 16px; }
.microbars i { display: block; background: var(--lime); height: 5px; border-radius: 2px; }
.microbars i:nth-child(1) { flex: 48; }.microbars i:nth-child(2) { flex: 32; opacity: .8; }.microbars i:nth-child(3) { flex: 24; opacity: .65; }.microbars i:nth-child(4) { flex: 14; opacity: .5; }.microbars i:nth-child(5) { flex: 10; opacity: .35; }
.overdue-copy { display: flex; align-items: center; gap: 6px; color: var(--orange); }
.overdue-copy::before { content: ''; width: 5px; height: 5px; background: var(--orange); border-radius: 50%; }
.paid-copy { display: flex; align-items: center; gap: 5px; }
.paid-copy .icon { color: var(--paid); width: 13px; height: 13px; }
.invoices { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; }
.section-heading { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 24px 24px 20px; }
h2 { margin: 0; font-size: 16px; line-height: 1.4; letter-spacing: -.3px; font-weight: 600; }
.section-heading p { margin: 4px 0 0; color: var(--muted); font-size: 12px; }
.sort-control { display: flex; align-items: center; gap: 8px; font-size: 11px; color: var(--subtle); }
.sort-control .icon { width: 15px; height: 15px; }
.sort-control select { color: var(--subtle); border: 0; background: transparent; font-size: 11px; min-height: 44px; padding-right: 4px; cursor: pointer; max-width: 150px; }
.list-toolbar { display: flex; justify-content: space-between; align-items: center; gap: 20px; padding: 0 24px 20px; }
.tabs { display: flex; align-items: center; gap: 4px; background: #f3f4ef; border-radius: var(--radius-sm); padding: 4px; }
.tab { min-height: 32px; display: flex; align-items: center; gap: 6px; padding: 6px 12px; background: transparent; border-radius: 4px; font-size: 11px; font-weight: 500; color: var(--subtle); position: relative; }
.tab::after { content: ''; position: absolute; inset: -6px 0; }
.tab:hover { color: var(--ink); background: #e9ece3; }
.tab.active { color: var(--ink); background: var(--surface); box-shadow: 0 1px 3px #1d2c1712; }
.tab-count { font-size: 9px; color: var(--subtle); background: #e9ece3; border-radius: 3px; min-width: 16px; padding: 0 3px; line-height: 16px; text-align: center; }
.tab:not(.active) .tab-count { background: transparent; }
.search { position: relative; display: flex; align-items: center; width: 224px; flex-shrink: 0; }
.search .icon { position: absolute; left: 12px; width: 16px; height: 16px; color: var(--subtle); pointer-events: none; }
.search input { min-width: 0; width: 100%; height: 40px; padding: 8px 12px 8px 36px; border: 1px solid var(--control); border-radius: var(--radius-sm); background: var(--surface); color: var(--ink); font-size: 11px; }
.search input::placeholder { color: var(--muted); }
.table-scroll { width: 100%; overflow-x: auto; position: relative; }
table { border-collapse: collapse; width: 100%; text-align: left; white-space: nowrap; }
thead { background: #f8f9f5; color: var(--subtle); font-size: 10px; }
th { font-weight: 500; height: 42px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
th, td { padding: 0 16px; }
th:first-child, td:first-child { padding-left: 24px; }
th:last-child, td:last-child { padding-right: 16px; text-align: right; }
td { height: 76px; font-size: 12px; border-bottom: 1px solid var(--line); }
tr:last-child td { border-bottom: 0; }
tbody tr:hover { background: #fbfcf8; }
.col-invoice { width: 15%; }.col-client { width: 32%; }.col-amount { width: 16%; }.col-status { width: 17%; }.col-due { width: 17%; }.col-action { width: 3%; }
.invoice-id { background: transparent; padding: 12px 0; font-size: 11px; color: var(--subtle); font-variant-numeric: tabular-nums; }
.invoice-id:hover { color: var(--green); text-decoration: underline; text-underline-offset: 4px; }
.client-cell { display: flex; align-items: center; gap: 12px; }
.client-avatar { width: 34px; height: 34px; display: grid; place-items: center; border-radius: 8px; font-size: 11px; font-weight: 600; flex-shrink: 0; }
.client-info { min-width: 0; }
.client-name { font-size: 12px; font-weight: 550; }
.client-project { font-size: 10px; color: var(--muted); margin-top: 2px; }
.amount { font-size: 12px; font-weight: 550; font-variant-numeric: tabular-nums; letter-spacing: -.2px; }
.status { display: inline-flex; align-items: center; gap: 5px; padding: 4px 8px; border-radius: 5px; font-size: 10px; line-height: 1.4; font-weight: 500; }
.status::before { content: ''; width: 4px; height: 4px; border-radius: 50%; background: currentColor; }
.status.pending { color: var(--pending); background: var(--pending-tint); }.status.overdue { color: var(--orange); background: var(--orange-tint); }.status.paid { color: var(--paid); background: var(--paid-tint); }.status.draft { color: var(--draft); background: var(--draft-tint); }
.due-date { color: var(--subtle); font-size: 11px; font-variant-numeric: tabular-nums; }
.due-note { font-size: 9px; color: var(--orange); margin-top: 1px; }
.row-action { width: 32px; height: 44px; }
.row-action .icon { width: 17px; height: 17px; }
.table-footer { display: flex; align-items: center; justify-content: space-between; padding: 12px 24px; border-top: 1px solid var(--line); font-size: 10px; color: var(--subtle); min-height: 64px; gap: 12px; }
.pagination { display: flex; align-items: center; gap: 6px; }
.page-button { min-width: 32px; min-height: 36px; position: relative; border-radius: 5px; background: transparent; color: var(--subtle); font-size: 11px; }
.page-button::after { content: ''; position: absolute; inset: -4px 0; }
.page-button:hover:not(:disabled) { background: var(--sidebar); }
.page-button.active { background: var(--green-tint); color: var(--green); font-weight: 600; }
.page-button .icon { width: 15px; height: 15px; }
.page-end { display: flex; align-items: center; justify-content: center; gap: 6px; margin-top: 24px; font-size: 10px; color: var(--muted); }
.page-end .icon { width: 12px; height: 12px; }
.empty { text-align: center; padding: 48px 24px; }
.empty .icon { width: 28px; height: 28px; color: var(--subtle); margin-bottom: 12px; }
.empty h3 { font-size: 15px; font-weight: 550; margin: 0 0 4px; }.empty p { font-size: 12px; color: var(--muted); margin: 0 0 16px; }
[hidden] { display: none "'!important; }
dialog { border: 0; border-radius: 14px; padding: 0; width: min(520px, calc(100% - 32px)); max-height: calc(100dvh - 40px); color: var(--ink); background: var(--surface); box-shadow: var(--shadow); }
dialog::backdrop { background: #17271f66; backdrop-filter: blur(3px); }
.dialog-header { display: flex; align-items: flex-start; justify-content: space-between; padding: 24px 24px 16px; gap: 16px; }
.dialog-header h2 { font-size: 22px; letter-spacing: -.6px; }
.dialog-header p { margin: 6px 0 0; color: var(--subtle); font-size: 12px; }
.dialog-header .icon-btn { margin: -8px -8px 0 0; flex-shrink: 0; }
.form-body { padding: 4px 24px 24px; }
.field { margin-top: 16px; }
.field label { display: block; font-size: 12px; font-weight: 500; margin-bottom: 8px; }
.field input, .field select { width: 100%; min-height: 44px; background: var(--surface); color: var(--ink); border: 1px solid var(--control); border-radius: var(--radius-sm); padding: 10px 12px; font-size: 13px; }
.field input::placeholder { color: var(--muted); }.field input[aria-invalid="true"] { border-color: var(--orange); }
.form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.field-error { font-size: 11px; margin: 5px 0 0; color: var(--orange); }
.field-note { font-size: 11px; color: var(--subtle); margin: 6px 0 0; }
.dialog-footer { display: flex; justify-content: flex-end; gap: 8px; border-top: 1px solid var(--line); padding: 16px 24px; background: #fafbf8; }
.detail-body { padding: 0 24px 24px; }
.detail-amount { font-size: 44px; letter-spacing: -1.5px; font-variant-numeric: tabular-nums; margin: 8px 0 24px; line-height: 1.2; }
.detail-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px 16px; margin: 0; }
.detail-grid dt { font-size: 11px; color: var(--subtle); margin-bottom: 5px; }.detail-grid dd { margin: 0; font-size: 13px; overflow-wrap: anywhere; }
.detail-project { padding: 20px 0 0; margin-top: 24px; border-top: 1px solid var(--line); color: var(--subtle); font-size: 12px; }
.detail-project strong { display: block; font-size: 11px; font-weight: 500; margin-bottom: 8px; }
.toast { position: fixed; bottom: 24px; left: calc(50% + 112px); transform: translateX(-50%); display: flex; align-items: center; gap: 10px; padding: 14px 20px; border-radius: 8px; background: var(--green); color: white; box-shadow: var(--shadow); z-index: 20; max-width: calc(100% - 32px); font-size: 12px; }
.toast .icon { width: 16px; height: 16px; }
.menu-backdrop { display: none; }
@media (min-width: 1600px) { .content { padding-top: 48px; }.stat { padding: 24px 28px; } td { height: 84px; } }
@media (max-width: 1200px) { .sidebar { width: 200px; padding-left: 12px; padding-right: 12px; }.main { margin-left: 200px; }.topbar { padding: 0 28px; }.content { padding: 32px 28px; }.stats { gap: 16px; }.stat { padding: 20px; }.list-toolbar { gap: 12px; padding-left: 20px; padding-right: 20px; }.tab { padding-left: 8px; padding-right: 8px; }.search { width: 184px; } th, td { padding-left: 12px; padding-right: 12px; }.toast { left: calc(50% + 100px); } }
@media (max-width: 1020px) { .sidebar { width: 184px; }.main { margin-left: 184px; }.content { padding: 28px 24px; }.topbar { padding: 0 24px; }.stat { padding: 16px; }.stat-value { font-size: 31px; }.stat-bottom { font-size: 10px; }.microbars { display: none; }.list-toolbar { flex-wrap: wrap; }.search { width: 100%; }.tabs { width: 100%; justify-content: flex-start; }.tab { flex: 1; justify-content: center; }.client-avatar { display: none; }.col-client { width: 27%; }.stat-top { font-size: 11px; }.toast { left: calc(50% + 92px); } }
@media (max-width: 760px) {
 .sidebar { width: 224px; transform: translateX(-100%); transition: transform var(--speed); }.sidebar.open { transform: translateX(0); }.main { margin-left: 0; }.menu-toggle { display: inline-flex !important; margin-left: -8px; }.topbar { height: 64px; padding: 0 20px; }.breadcrumb { margin-right: auto; gap: 8px; }.topbar-right .date { display: none; }.sample { font-size: 9px; }.content { padding: 28px 20px; }.page-heading { margin-bottom: 24px; }h1 { font-size: 28px; }.stats { gap: 12px; margin-bottom: 28px; }.stat-value { font-size: 28px; }.stat-top { gap: 6px; }.stat-top > .icon { display: none; }.stat-bottom { line-height: 1.5; }.menu-backdrop.open { display: block; position: fixed; inset: 0; background: #15281e66; z-index: 4; }.toast { left: 50%; }.client-avatar { display: grid; }.table-scroll table { min-width: 680px; }.tab { min-height: 36px; }.page-end { margin-top: 20px; }
}
@media (max-width: 520px) {
 .content { padding: 24px 16px; }.topbar { padding: 0 16px; }.page-heading { align-items: center; gap: 8px; }.page-description { font-size: 11px; }h1 { font-size: 26px; }.page-heading .btn { padding-left: 12px; padding-right: 12px; font-size: 11px; }
 .stats { grid-template-columns: 1fr 1fr; gap: 12px; }.stat-primary { grid-column: 1 / -1; padding: 20px; }.stat-primary .stat-value { font-size: 40px; }.stat-primary .stat-top { margin-bottom: 12px; }.stat-primary .stat-top > .icon { display: block; }.stat-primary .microbars { display: flex; width: 100px; }.stat-primary .stat-bottom { font-size: 11px; }.stat:not(.stat-primary) { padding: 16px; }.stat-value { font-size: 27px; }.stat-top { margin-bottom: 10px; }.stat-bottom { margin-top: 12px; font-size: 10px; }.stat-top { font-size: 11px; }.stat-link { width: 20px; height: 20px; }
 .section-heading { padding: 20px 16px 12px; align-items: flex-start; }.section-heading p { font-size: 10px; }.sort-control { gap: 2px; margin-top: -7px; }.sort-control > .icon { display: none; }.sort-control select { font-size: 10px; max-width: 114px; }.list-toolbar { padding: 0 16px 16px; gap: 12px; }.tab { font-size: 10px; padding: 6px; gap: 4px; }.tab-count { font-size: 8px; min-width: 13px; }.table-footer { padding: 12px 16px; font-size: 9px; }.page-button { min-width: 30px; }.form-row { grid-template-columns: 1fr; gap: 0; }.dialog-header { padding: 24px 20px 12px; }.form-body, .detail-body { padding-left: 20px; padding-right: 20px; }.dialog-footer { padding: 16px 20px; }.toast { width: max-content; }.invoices { border-radius: 8px; }
}
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none !important; scroll-behavior: auto !important; } }
</style>
</head>
<body>
<svg xmlns="http://www.w3.org/2000/svg" class="icon-sprite" aria-hidden="true"><defs>
<symbol id="i-grid" viewBox="0 0 24 24"><rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/></symbol>
<symbol id="i-invoice" viewBox="0 0 24 24"><path d="M6 3h12v18l-3-2-3 2-3-2-3 2z"/><path d="M9 7h6M9 11h6M9 15h3"/></symbol>
<symbol id="i-clock" viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></symbol>
<symbol id="i-alert" viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 7v6m0 4h.01"/></symbol>
