 ].map((v,i) => ({id:"'`INV-${year}-${String(48-i).padStart(3,'"'0')}"'`,client:v[0],project:v[1],amount:v[2],status:v[3],due:dateOffset(v[4]),initials:v[5],background:v[6],color:v[7],created:Date.now()-i*86400000,paidAt:v[3]==='"'paid'?dateISO(now):null}));
