   return "'`<tr><td><button class="invoice-id" data-invoice="${escape(i.id)}">${escape(i.id)}</button></td><td><div class="client-cell"><span class="client-avatar" style="background:${palette?palette.background:'"'#e4eade'};color:"'${palette?palette.color:'"'#486442'}\" aria-hidden=\"true\">"'${escape(palette?palette.initials:initials)}</span><div class="client-info"><div class="client-name">${escape(i.client)}</div><div class="client-project">${escape(i.project)}</div></div></div></td><td class="amount">${money(i.amount)}</td><td><span class="status ${status}">${status==='"'pending'?'Pending':status[0].toUpperCase()+status.slice(1)}</span></td><td><div class=\"due-date\">"'${formatDate(i.due)}</div>${status==='"'overdue'?"'`<div class="due-note">${days} day${days===1?'"'':'s'} overdue</div>"'`:'"''}</td><td><button class=\"icon-btn row-action\" data-invoice=\""'${escape(i.id)}" aria-label="View invoice ${escape(i.id)} for ${escape(i.client)}">${icon('"'more')}</button></td></tr>"'`;
  }).join('"'');
